Read the program given below carefully and find the correct output.
```
public class Main {
    public static void main(String[] args) {
        int[] arr = {1,3,4,5,6,8,6,13,34,45,65,76,38};
        int count = 0;

        for (int i = 0; i < 13; i++) {
            if (arr[i] % 3 == 0) {
                count++;
            }
        }

        System.out.println(count); // tracing of count 
        count = count % 2;
        System.out.println(count); // tracing of count

        if (count == 0) {
            System.out.println("even number of multiple of 3");
        } else {
            System.out.println("odd number of multiples of 3");
        }
    }
}

